using UnityEngine;
namespace Alterverse.Visuals
{
public sealed class RealityCoreShell:MonoBehaviour
{
private Transform root,heart;private Color dark,energy,ground;
public void Build(bool zero){dark=zero?StylizedArtDirection.ZeroDark:StylizedArtDirection.LumenDark;energy=zero?StylizedArtDirection.ZeroEnergy:StylizedArtDirection.LumenEnergy;ground=zero?StylizedArtDirection.ZeroGround:StylizedArtDirection.LumenGround;root=new GameObject("DF_RealityCoreShell").transform;root.SetParent(transform,false);BuildFoundation(zero);BuildReactor(zero);BuildFineDetails(zero);}
private void BuildFoundation(bool zero){Part("CorePlatform",PrimitiveType.Cylinder,new Vector3(0,.10f,0),new Vector3(3.15f,.11f,3.15f),Color.Lerp(ground,dark,.35f),Vector3.zero);for(int i=0;i<6;i++){float a=i*Mathf.PI/3f;Vector3 p=new Vector3(Mathf.Cos(a)*2.65f,.24f,Mathf.Sin(a)*2.65f);Transform butt=Part("CoreButtress",PrimitiveType.Cube,p,new Vector3(.78f,.34f,.38f),dark,new Vector3(0,-a*Mathf.Rad2Deg+90,zero?(i%2==0?8:-8):0));Part("CoreConduit",PrimitiveType.Cube,p+Vector3.up*.32f,new Vector3(.42f,.045f,.065f),energy,new Vector3(0,-a*Mathf.Rad2Deg+90,0),true);}}
private void BuildReactor(bool zero){for(int i=0;i<4;i++){float a=(i*90+45)*Mathf.Deg2Rad;float lean=zero?(i%2==0?14:-10):0;Part("ReactorPylon",PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*1.28f,1.75f,Mathf.Sin(a)*1.28f),new Vector3(.22f,2.85f,.28f),dark,new Vector3(lean,-a*Mathf.Rad2Deg,zero?lean*.45f:0));Part("PylonEnergy",PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*1.18f,1.78f,Mathf.Sin(a)*1.18f),new Vector3(.065f,2.05f,.075f),energy,new Vector3(lean,-a*Mathf.Rad2Deg,zero?lean*.45f:0),true);}Part("LowerReactor",PrimitiveType.Cylinder,new Vector3(0,.72f,0),new Vector3(.82f,.52f,.82f),dark,Vector3.zero);heart=Part("RealityHeart",PrimitiveType.Sphere,new Vector3(0,2.05f,0),Vector3.one*.72f,energy,Vector3.zero,true);Part("UpperCrystal",PrimitiveType.Cube,new Vector3(0,3.05f,0),new Vector3(.42f,1.55f,.42f),energy,new Vector3(zero?18:0,45,zero?12:0),true);for(int i=0;i<4;i++){float a=(i*90+45)*Mathf.Deg2Rad;Part("CrownShard",PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*.62f,3.28f,Mathf.Sin(a)*.62f),new Vector3(.12f,1.18f,.12f),energy,new Vector3(zero?i*9:0,-i*45,zero?(i%2==0?16:-16):0),true);}}
private void BuildFineDetails(bool zero){for(int ring=0;ring<2;ring++){int count=ring==0?12:8;float radius=ring==0?2.18f:1.72f;for(int i=0;i<count;i++){float a=(i*(360f/count)+(ring*12f))*Mathf.Deg2Rad;Vector3 p=new Vector3(Mathf.Cos(a)*radius,.34f+ring*.14f,Mathf.Sin(a)*radius);Part("MicroBrace",PrimitiveType.Cube,p,new Vector3(.16f,.24f,.34f),i%3==0?energy:dark,new Vector3(zero?(i%2==0?7:-7):0,-a*Mathf.Rad2Deg+90,0),i%3==0);}}for(int i=0;i<6;i++){float a=(i*60+30)*Mathf.Deg2Rad;for(int h=0;h<3;h++){Vector3 p=new Vector3(Mathf.Cos(a)*(1.05f-h*.08f),1.05f+h*.68f,Mathf.Sin(a)*(1.05f-h*.08f));Part("PylonNode",PrimitiveType.Cube,p,new Vector3(.20f,.12f,.20f),energy,new Vector3(zero?h*8:0,-a*Mathf.Rad2Deg,zero?(i%2==0?6:-6):0),true);}}for(int i=0;i<6;i++){float a=i*60*Mathf.Deg2Rad;Part("CrownNeedle",PrimitiveType.Cube,new Vector3(Mathf.Cos(a)*.42f,3.72f+((i%2)*.12f),Mathf.Sin(a)*.42f),new Vector3(.07f,.72f,.07f),energy,new Vector3(zero?(i%2==0?12:-12):0,-i*60,zero?8:0),true);}}
private Transform Part(string n,PrimitiveType type,Vector3 p,Vector3 s,Color c,Vector3 r,bool pulse=false){GameObject g=GameObject.CreatePrimitive(type);g.name="DF_"+n;g.transform.SetParent(root,false);g.transform.localPosition=p;g.transform.localScale=s;g.transform.localRotation=Quaternion.Euler(r);Collider col=g.GetComponent<Collider>();if(col!=null)col.enabled=false;Renderer renderer=g.GetComponent<Renderer>();if(renderer!=null){Material m=renderer.material;m.color=c;if(m.HasProperty("_BaseColor"))m.SetColor("_BaseColor",c);if(pulse){m.EnableKeyword("_EMISSION");m.SetColor("_EmissionColor",c*3.2f);}}if(pulse)g.AddComponent<ArenaLightPulse>();return g.transform;}
}
}